<?php
namespace App\Actions\ServiceOrders;use App\Domain\ServiceOrders\ServiceOrderStatusTransition;use App\Enums\ServiceOrderStatus;use App\Models\{ServiceOrder,ServiceOrderStatusHistory,User};use Illuminate\Support\Facades\DB;
class ConfirmServiceOrder{public function execute(ServiceOrder $order,?User $by=null):ServiceOrder{return DB::transaction(function()use($order,$by){$o=ServiceOrder::lockForUpdate()->findOrFail($order->id);$old=(string)$o->status;app(ServiceOrderStatusTransition::class)->assertAllowed($old,ServiceOrderStatus::CONFIRMED);$o->update(['status'=>ServiceOrderStatus::CONFIRMED]);ServiceOrderStatusHistory::create(['service_order_id'=>$o->id,'old_status'=>$old,'new_status'=>ServiceOrderStatus::CONFIRMED,'changed_by'=>$by?$by->id:null]);return$o->refresh();});}}
